204	  private readonly _layout: WorkLayoutConstants;
205	  private readonly _camPadX: number;
206	  private readonly _camPadY: number;
207	  private _baseCamZ: number;
208	  private _isDragging = false;
209	  private _dragPrevious: WorksPointerSample = { x: 0, y: 0 };
210	  private _targetX = 0;
211	  private _targetY = 0;
212	  private _velocityX = 0;
213	  private _velocityY = 0;
214	  private _targetZ: number;
215	  private _dynClampMinX: number;
216	  private _dynClampMaxX: number;
217	  private _dynClampMinY: number;
218	  private _dynClampMaxY: number;
219	
220	  constructor(
221	    layout: WorkLayoutConstants,
222	    camPadX: number,
223	    camPadY: number,
224	    camZ: number,
225	  ) {
226	    this._layout = layout;
227	    this._camPadX = camPadX;
228	    this._camPadY = camPadY;
229	    this._baseCamZ = camZ;
230	    this._targetZ = camZ;
231	    this._dynClampMinX = -camPadX;
232	    this._dynClampMaxX = camPadX;
233	    this._dynClampMinY = -camPadY;
234	    this._dynClampMaxY = camPadY;
235	  }
236	
237	  setDynamicClamp(positions: ReadonlyArray<WorksScatterPosition>): void {
238	    if (positions.length === 0) {
239	      this._dynClampMinX = this._dynClampMaxX = 0;
240	      this._dynClampMinY = this._dynClampMaxY = 0;
241	      return;
242	    }
243	    const MARGIN = 8;
244	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
245	    for (const p of positions) {
246	      if (p.x < minX) minX = p.x;
247	      if (p.x > maxX) maxX = p.x;
248	      if (p.y < minY) minY = p.y;
249	      if (p.y > maxY) maxY = p.y;
250	    }
251	    this._dynClampMinX = minX - MARGIN;
252	    this._dynClampMaxX = maxX + MARGIN;
253	    this._dynClampMinY = minY - MARGIN;
254	    this._dynClampMaxY = maxY + MARGIN;
255	  }
256	
257	  activateScatter(): void {
258	    this._targetZ = this._baseCamZ;
259	  }
260	
261	  setTargetPosition(targetX: number, targetY: number): void {
262	    this._targetX = targetX;
263	    this._targetY = targetY;
264	  }
265	
266	  setTargetZ(targetZ: number): void {
267	    this._targetZ = targetZ;
268	  }
269	
270	  readBaseCamZ(): number {
271	    return this._baseCamZ;
272	  }
273	
274	  setBaseCamZ(baseCamZ: number): void {
275	    this._baseCamZ = baseCamZ;
276	    this._targetZ = baseCamZ;
277	  }
278	
279	  primeFromCamera(camera: THREE.PerspectiveCamera): void {
280	    this._targetX = camera.position.x;
281	    this._targetY = camera.position.y;
282	    this._targetZ = camera.position.z;
283	  }
284	
285	  primeFromCameraPosition(targetX: number, targetY: number, targetZ: number): void {
286	    this._targetX = targetX;
287	    this._targetY = targetY;
288	    this._targetZ = targetZ;
289	  }
290	
291	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
292	    this._isDragging = true;
293	    this._dragPrevious = { ...pointer };
294	    this._velocityX = 0;
295	    this._velocityY = 0;
296	    this._targetX = camera.position.x;
297	    this._targetY = camera.position.y;
298	  }
299	
300	  endDrag(): void {
301	    this._isDragging = false;
302	  }
303	
304	  updateDrag(
305	    viewport: WorksViewportSnapshot,
306	    halfView: WorksHalfViewBounds,
307	    pointer: WorksPointerSample,
308	    velMultiplier = 1,
309	  ): void {
310	    if (!this._isDragging) return;
311	    const dx = pointer.x - this._dragPrevious.x;
312	    const dy = pointer.y - this._dragPrevious.y;
313	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
314	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
315	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
316	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7 * velMultiplier;
317	    this._targetX = Math.max(
318	      this._dynClampMinX + halfView.hW,
319	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
320	    );
321	    this._targetY = Math.max(
322	      this._dynClampMinY + halfView.hH,
323	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
324	    );
325	    this._dragPrevious = { ...pointer };
326	  }
327	
328	  updateFrame(camera: THREE.Camera, delta: number): void {
329	    if (this._isDragging) {
330	      const decay = Math.pow(this._layout.velDecay, delta * 60);
331	      this._velocityX *= decay;
332	      this._velocityY *= decay;
333	      this._targetX += this._velocityX * delta * 60;
334	      this._targetY += this._velocityY * delta * 60;
335	    }
336	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
337	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
338	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
339	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
340	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
341	    camera.lookAt(camera.position.x, camera.position.y, 0);
342	  }
343	
344	  get isDragging(): boolean {
345	    return this._isDragging;
346	  }
347	}
