905	    canvas.addEventListener("pointerup", onPointerUp);
906	    canvas.addEventListener("pointercancel", onPointerCancel);
907	    canvas.addEventListener("pointerleave", onPointerLeave);
908	    window.addEventListener("resize", onResize);
909	    this.cleanup.push(
910	      () => canvas.removeEventListener("pointermove", onPointerMove),
911	      () => canvas.removeEventListener("pointerdown", onPointerDown),
912	      () => canvas.removeEventListener("pointerup", onPointerUp),
913	      () => canvas.removeEventListener("pointercancel", onPointerCancel),
914	      () => canvas.removeEventListener("pointerleave", onPointerLeave),
915	      () => window.removeEventListener("resize", onResize),
916	    );
917	  }
