22	function applyWorksIntroEase(progress: number): number {
23	  const clamped = Math.max(0, Math.min(1, progress));
24	  if (WORKS_INTRO_DEFAULT_EASE === "power3.inOut") {
25	    return clamped < 0.5
26	      ? 4 * clamped * clamped * clamped
27	      : 1 - Math.pow(-2 * clamped + 2, 3) / 2;
28	  }
29	  return clamped;
30	}
