25	  constructor(options: WorkModalToggleOptions = {}) {
26	    super({ selector: `#${options.hostId ?? "work-modal-host"}` });
27	    this.setOption(options);
28	  }
29	
30	  override init(): void {
31	    if (this.isDisposed) return;
32	    this.mount();
33	  }
34	
35	  setOption(options: WorkModalToggleOptions = {}): void {
36	    if (options.root !== undefined) this._root = options.root;
