57	  }
58	
59	  override getVisibleState(): boolean {
60	    return this._activeModal != null;
61	  }
62	
63	  private _bindTriggers(): void {
64	    this._triggerAbortController?.abort();
65	    this._triggerAbortController = new AbortController();
66	    const signal = this._triggerAbortController.signal;
67	    const scope = this._root ?? document;
68	    scope.addEventListener(
69	      "click",
70	      (event) => {
71	        const target = event.target;
72	        if (!(target instanceof Element)) return;
73	        const trigger = target.closest<HTMLElement>(this._triggerSelector);
74	        if (!trigger) return;
75	        if (this._root && !this._root.contains(trigger)) return;
76	        event.preventDefault();
77	        const endpoint = this._resolveEndpoint(trigger);
78	        if (endpoint) this._schedule(endpoint);
79	      },
80	      { signal },
81	    );
82	  }
83	
84	  private _resolveEndpoint(trigger: HTMLElement): string | null {
85	    const item = trigger.closest<HTMLElement>("[data-work-no]");
86	    const workNo = item?.dataset.workNo?.trim();
87	    if (!workNo) return null;
88	    const list = trigger.closest<HTMLElement>("[data-work-modal-endpoint-template]");
89	    const template = list?.dataset.workModalEndpointTemplate?.trim();
90	    const endpointTemplate =
91	      template && template.length > 0 ? template : "/works/modal-component/{no}";
92	    return endpointTemplate.replace("{no}", encodeURIComponent(workNo));
93	  }
94	
95	  private _schedule(endpoint: string): void {
96	    if (this._openLock) return;
97	    this._pendingEndpoint = endpoint;
98	    this._openDebounce.runDebounce(() => {
99	      if (this._openLock) return;
100	      const next = this._pendingEndpoint;
101	      this._pendingEndpoint = null;
102	      if (!next) return;
103	      this._openLock = true;
104	      void this._openByEndpoint(next);
105	    });
106	  }
107	
108	  private async _openByEndpoint(endpoint: string): Promise<void> {
109	    this._requestAbortController?.abort();
110	    this._requestAbortController = new AbortController();
111	    try {
112	      const modal = await this._fetchModal(endpoint, this._requestAbortController.signal);
113	      this._show(modal);
114	    } catch (error) {
115	      if (!(error instanceof DOMException && error.name === "AbortError")) {
116	        throw error;
117	      }
118	    } finally {
119	      this._requestAbortController = null;
120	      window.setTimeout(() => {
121	        this._openLock = false;
122	      }, DEBOUNCE_MS_MODAL_OPEN);
123	    }
124	  }
125	
126	  private async _fetchModal(
127	    endpoint: string,
128	    signal: AbortSignal,
129	  ): Promise<HTMLElement> {
130	    const no = endpoint.split("/").pop() ?? "";
131	    const html = await fetchWorksModalHtml(no, signal);
132	    const doc = new DOMParser().parseFromString(html, "text/html");
133	    const modal = doc.querySelector<HTMLElement>(this._modalRootSelector);
134	    if (!modal) {
135	      throw new Error(`Missing modal root selector: ${this._modalRootSelector}`);
136	    }
137	    return modal;
138	  }
139	
140	  private _show(incomingModal: HTMLElement): void {
141	    this._hide(true);
142	    const host = this._ensureHost();
143	    const modal = incomingModal.cloneNode(true) as HTMLElement;
144	    const panel = modal.querySelector<HTMLElement>(".no-work-modal__panel");
145	    panel?.setAttribute("data-lenis-prevent", "true");
146	    panel?.setAttribute("data-lenis-prevent-wheel", "true");
147	    panel?.setAttribute("data-lenis-prevent-touch", "true");
148	    host.replaceChildren(modal);
149	    void modal.offsetWidth;
150	    modal.classList.add("is-open");
151	    this._activeModal = modal;
152	    this._visible = true;
153	    this._releaseScrollLock?.();
154	    this._releaseScrollLock = ScrollLock.lock({ pauseLenis: false });
155	    this._bindModalEvents(modal);
156	  }
157	
158	  private _bindModalEvents(modal: HTMLElement): void {
159	    this._activeAbortController?.abort();
160	    const abortController = new AbortController();
161	    this._activeAbortController = abortController;
162	    const closeNodes = Array.from(
163	      modal.querySelectorAll<HTMLElement>(this._closeSelector),
164	    );
165	    closeNodes.forEach((node) =>
166	      node.addEventListener("click", () => this._hide(), {
167	        signal: abortController.signal,
168	      }),
169	    );
170	    document.addEventListener(
171	      "keydown",
172	      (event) => {
173	        if (event.key === "Escape") this._hide();
174	      },
175	      { signal: abortController.signal },
176	    );
177	  }
178	
179	  private _hide(immediate = false): void {
180	    if (!this._activeModal) return;
181	    this._requestAbortController?.abort();
182	    this._requestAbortController = null;
183	    this._activeAbortController?.abort();
184	    this._activeAbortController = null;
185	    if (this._closeTimer !== null) {
186	      window.clearTimeout(this._closeTimer);
187	      this._closeTimer = null;
188	    }
189	    const closingModal = this._activeModal;
190	    const reduceMotion =
191	      ResponsiveRuntime.getDefault().getSnapshot().flags.reducedMotion;
192	    const closeMs = immediate || reduceMotion ? 0 : 320;
193	    closingModal.classList.remove("is-open");
194	    closingModal.classList.add("is-closing");
195	    const finalize = (): void => {
196	      this._ensureHost().replaceChildren();
197	      this._activeModal = null;
198	      this._visible = false;
199	      this._releaseScrollLock?.();
200	      this._releaseScrollLock = null;
201	    };
202	    if (closeMs === 0) {
203	      finalize();
204	      return;
205	    }
206	    this._closeTimer = window.setTimeout(() => {
207	      finalize();
208	      this._closeTimer = null;
209	    }, closeMs);
210	  }
211	
212	  private _ensureHost(): HTMLElement {
213	    const existing = document.getElementById(this._hostId);
214	    if (existing) {
215	      this.setElement(existing);
216	      return existing;
217	    }
218	    const host = document.createElement("div");
219	    host.id = this._hostId;
220	    Aria.setLive(host, "polite");
221	    document.body.appendChild(host);
222	    this.setElement(host);
223	    return host;
224	  }
225	
226	  override dispose(): void {
227	    this._hide(true);
228	    this._triggerAbortController?.abort();
229	    this._triggerAbortController = null;
230	    this._requestAbortController?.abort();
231	    this._requestAbortController = null;
232	    this._activeAbortController?.abort();
233	    this._activeAbortController = null;
234	    if (this._closeTimer !== null) {
235	      window.clearTimeout(this._closeTimer);
236	      this._closeTimer = null;
237	    }
238	    this._openDebounce.offCancel();
239	    this._activeModal = null;
240	    this._openLock = false;
241	    this._pendingEndpoint = null;
242	    this._releaseScrollLock?.();
243	    this._releaseScrollLock = null;
244	    super.dispose();
245	  }
246	}
